using namespace std;

class Solution {
public:
    int maxProductPath(vector<vector<int>>& grid) {
        int m = grid.size(), n = grid[0].size();
        vector<vector<long long>> dp_max(m, vector<long long>(n, 0));
        vector<vector<long long>> dp_min(m, vector<long long>(n, 0));
        dp_max[0][0] = dp_min[0][0] = grid[0][0];
        for (int r = 1; r < m; ++r) {
            dp_max[r][0] = dp_min[r][0] = dp_max[r-1][0] * grid[r][0];
        }
        for (int c = 1; c < n; ++c) {
            dp_max[0][c] = dp_min[0][c] = dp_max[0][c-1] * grid[0][c];
        }
        for (int r = 1; r < m; ++r) {
            for (int c = 1; c < n; ++c) {
                long long val = grid[r][c];
                long long a = dp_max[r-1][c] * val;
                long long b = dp_min[r-1][c] * val;
                long long d = dp_max[r][c-1] * val;
                long long e = dp_min[r][c-1] * val;
                dp_max[r][c] = max({a, b, d, e});
                dp_min[r][c] = min({a, b, d, e});
            }
        }
        long long ans = dp_max[m-1][n-1];
        long long MOD = 1e9 + 7;
        return ans >= 0 ? ans % MOD : -1;
    }
};

class Solution {
    public int maxProductPath(int[][] grid) {
        int m = grid.length, n = grid[0].length;
        long[][] dpMax = new long[m][n];
        long[][] dpMin = new long[m][n];
        dpMax[0][0] = dpMin[0][0] = grid[0][0];
        for (int r = 1; r < m; ++r) {
            dpMax[r][0] = dpMin[r][0] = dpMax[r-1][0] * grid[r][0];
        }
        for (int c = 1; c < n; ++c) {
            dpMax[0][c] = dpMin[0][c] = dpMax[0][c-1] * grid[0][c];
        }
        for (int r = 1; r < m; ++r) {
            for (int c = 1; c < n; ++c) {
                long val = grid[r][c];
                long a = dpMax[r-1][c] * val;
                long b = dpMin[r-1][c] * val;
                long d = dpMax[r][c-1] * val;
                long e = dpMin[r][c-1] * val;
                dpMax[r][c] = Math.max(Math.max(a, b), Math.max(d, e));
                dpMin[r][c] = Math.min(Math.min(a, b), Math.min(d, e));
            }
        }
        long ans = dpMax[m-1][n-1];
        long MOD = 1000000007L;
        return ans >= 0 ? (int)(ans % MOD) : -1;
    }
}

