var maxProductPath = function(grid) {
    const m = grid.length, n = grid[0].length;
    const dpMax = Array.from({ length: m }, () => Array(n).fill(0n));
    const dpMin = Array.from({ length: m }, () => Array(n).fill(0n));
    dpMax[0][0] = dpMin[0][0] = BigInt(grid[0][0]);
    for (let r = 1; r < m; ++r) {
        dpMax[r][0] = dpMin[r][0] = dpMax[r-1][0] * BigInt(grid[r][0]);
    }
    for (let c = 1; c < n; ++c) {
        dpMax[0][c] = dpMin[0][c] = dpMax[0][c-1] * BigInt(grid[0][c]);
    }
    for (let r = 1; r < m; ++r) {
        for (let c = 1; c < n; ++c) {
            const val = BigInt(grid[r][c]);
            const a = dpMax[r-1][c] * val;
            const b = dpMin[r-1][c] * val;
            const d = dpMax[r][c-1] * val;
            const e = dpMin[r][c-1] * val;
            let mx = a, mn = a;
            for (const x of [b, d, e]) {
                if (x > mx) mx = x;
                if (x < mn) mn = x;
            }
            dpMax[r][c] = mx;
            dpMin[r][c] = mn;
        }
    }
    const ans = dpMax[m-1][n-1];
    const MOD = 1000000007n;
    return ans >= 0n ? Number(ans % MOD) : -1;
};
